module string_generator(input clk,input rst_n,input start,input [7:0]n,input [4:0]k,output reg[1023:0]result,output reg[7:0]length_out,output reg valid,output reg error);localparam IDLE=3'd0,CHECK=3'd1,GEN_LOOP=3'd2,FINISH=3'd3,ERROR=3'd4;reg[2:0]state;reg[7:0]n_reg,k_reg;reg[1023:0]result_reg;reg[7:0]char_count,prefix_length,offset_counter;reg error_flag,valid_out,length_out_reg;always@(posedge clk or negedge rst_n)begin if(!rst_n)begin state<=IDLE;n_reg<=8'd0;k_reg<=4'd0;result_reg<={1024{1'b0}};char_count<=8'd0;prefix_length<=8'd0;offset_counter<=8'd0;error_flag<=1'b0;valid_out<=1'b0;length_out_reg<=8'd0;end else begin if(state==IDLE)begin if(start)begin state<=CHECK;n_reg<=n;k_reg<=k;end end else if(state==CHECK)begin if(k_reg>26||(k_reg==1&&n_reg>1)||(n_reg<k_reg))begin state<=ERROR;error_flag<=1'b1;end else begin if(n_reg==1&&k_reg==1)begin result_reg<={8'h61,{1024-8{1'b0}}};length_out_reg<=1;valid_out<=1'b1;state<=FINISH;end else begin prefix_length<=n_reg-(k_reg-2);state<=GEN_LOOP;char_count<=8'd0;offset_counter<=8'd0;end end end else if(state==GEN_LOOP)begin if(char_count<prefix_length)begin if(char_count[0]==0)begin result_reg[char_count*8+7:char_count*8]<=8'h61;end else begin result_reg[char_count*8+7:char_count*8]<=8'h62;end end else begin result_reg[char_count*8+7:char_count*8]<=8'h63+offset_counter;end if(char_count<n_reg)begin char_count<=char_count+1;end else begin state<=FINISH;valid_out<=1'b1;error_flag<=1'b0;length_out_reg<=n_reg;end if(char_count==prefix_length)begin offset_counter<=8'd0;end else if(char_count>prefix_length)begin if(offset_counter<(k_reg-2-1))begin offset_counter<=offset_counter+1;end end end else if(state==ERROR)begin error_flag<=1'b1;valid_out<=1'b0;end else if(state==FINISH)begin valid_out<=1'b1;error_flag<=1'b0;end end end assign result=result_reg;assign length_out=length_out_reg;assign valid=valid_out;assign error=error_flag;endmodule